# 3급 CH13 접속사 (121~130) 2차 감수
X(3, 121, r="unless는 if ~ not(~하지 않으면)과 같다. unless 뒤에 not을 또 쓰지 않는다.",
  n=["If를 쓰면 ‘서두르면 늦는다’가 되어 우리말과 반대이므로", "Unless는 ‘~하지 않으면’이라 우리말과 맞으므로", "When은 ‘~할 때’라 우리말과 맞지 않으므로", "Because는 ‘~ 때문에’라 우리말과 맞지 않으므로", "Although는 ‘비록 ~이지만’이라 우리말과 맞지 않으므로"],
  st="① 우리말에서 두 절을 잇는 말을 찾는다: {0}. → ② {1} → ③ 정답은 {a}.",
  R=("‘서두르지 않으면’", "부정의 조건인데 빈칸 뒤 you hurry에는 not이 없다. not의 뜻까지 담은 Unless(= If ~ not)를 쓴다."), B=("‘서두르지 않으면’", "부정의 조건인데 빈칸 뒤 you hurry에는 not이 없다. not의 뜻까지 담은 Unless(= If ~ not)를 쓴다."),
  C=("‘만약 비가 오면’", "긍정의 조건이므로 If를 쓴다. Unless를 쓰면 ‘비가 오지 않으면’이 된다."), D=("‘일을 마칠 때’", "조건이 아니라 때를 나타내므로 When을 쓴다."),
  E=("‘피곤하지만’", "앞뒤가 서로 반대되는 내용이므로 Although(비록 ~이지만)를 쓴다."), F=("‘아팠기 때문에’", "이유를 나타내므로 Because를 쓴다."))

X(3, 122, r="that 뒤에 명사만 오면 ‘저 ~’라는 지시형용사, 주어 + 동사가 오면 명사절을 이끄는 접속사다.",
  n=["뒤의 명사 book을 꾸미는 지시형용사(저 ~)이므로", "know의 목적어가 되는 절을 이끄는 접속사이므로", "문장의 주어가 되는 절을 이끄는 접속사이므로", "hope의 목적어가 되는 절을 이끄는 접속사이므로", "가주어 It이 가리키는 진주어절을 이끄는 접속사이므로"],
  st="① that 바로 뒤를 본다. 명사 하나가 오면 지시형용사, ‘주어 + 동사’가 오면 접속사다. → ② {0} 나머지는 that 뒤에 주어 + 동사가 이어진다. → ③ 정답은 {n}.",
  R="①만 that 뒤에 명사 book이 온다.", B="⑤만 that 뒤에 명사 book이 온다.", C="②만 that 뒤에 명사 movie가 온다.", D="②만 that 뒤에 명사 answer가 온다.", E="③만 that 뒤에 명사 student가 온다.", F="④만 that 뒤에 명사 building이 온다.")

X(3, 123, r="neither A nor B는 ‘A도 B도 아닌’이다. both A and B(둘 다), either A or B(둘 중 하나), not only A but also B = B as well as A(A뿐 아니라 B도).",
  n=["‘커피뿐 아니라 차도 마신다’는 뜻이므로", "‘커피나 차 중 하나를 마신다’는 뜻이므로", "‘커피와 차를 둘 다 마신다’는 뜻이므로", "neither A nor B로 ‘둘 다 마시지 않는다’를 나타내므로", "‘차뿐 아니라 커피도 마신다’는 뜻이므로"],
  st="① 우리말이 둘 다 부정하는 문장임을 확인한다: {0}. → ② ‘A도 B도 아닌’은 neither A nor B다. neither에 부정의 뜻이 있으므로 동사는 긍정형 그대로 쓴다. → ③ both, either, not only가 든 문장은 뜻이 다르다. 정답은 {n}.",
  R="‘커피도 차도 마시지 않는다’", B="‘커피도 차도 마시지 않는다’", C="‘노래도 못 부르고 춤도 못 춘다’", D="‘버스도 기차도 타지 않았다’", E="‘영화도 TV도 보지 않았다’", F="‘사과도 바나나도 좋아하지 않는다’")

X(3, 124, r="so 뒤에는 결과, because 뒤에는 이유가 온다.",
  n=["둘째 문장은 빈칸 뒤가 이유라 so를 쓸 수 없으므로", "첫 문장은 뒤가 결과라 so, 둘째 문장은 뒤가 이유라 because가 알맞으므로", "so와 because를 반대로 썼으므로", "첫 문장은 빈칸 뒤가 결과라 because를 쓸 수 없으므로", "although는 ‘비록 ~이지만’이라 둘째 문장과 맞지 않으므로"],
  st="① 빈칸 뒤의 절이 원인인지 결과인지 가른다. → ② {0} → ③ 뒤가 결과면 so, 뒤가 이유면 because다. 정답은 {a}.",
  R="첫 문장: 추웠다(원인) → 안에 있었다(결과). 뒤가 결과다. 둘째 문장: 따뜻한 옷을 가져왔다 ← 추웠다(이유). 뒤가 이유다.", B="첫 문장: 추웠다(원인) → 안에 있었다(결과). 뒤가 결과다. 둘째 문장: 따뜻한 옷을 가져왔다 ← 추웠다(이유). 뒤가 이유다.",
  C="① 발문이 알려 준 관계를 확인한다: 첫 빈칸은 대조, 둘째 빈칸은 선택. → ② 대조는 but, 선택은 or로 잇는다. → ③ 정답은 {a}.",
  D="첫 문장: 열심히 공부했다(원인) → 합격했다(결과). 뒤가 결과다. 둘째 문장: 열심히 공부했다 ← 합격하고 싶었다(이유). 뒤가 이유다.",
  E="① 발문이 알려 준 관계를 확인한다: 첫 빈칸은 대조, 둘째 빈칸은 시간. → ② 대조는 but, ‘~할 때’는 when으로 잇는다. → ③ 정답은 {a}.",
  F="① 발문이 알려 준 관계를 확인한다: 첫 빈칸은 선택, 둘째 빈칸은 결과. → ② 선택은 or, 결과는 so로 잇는다. → ③ 정답은 {a}.")

X(3, 125, r="not only A but also B(A뿐 아니라 B도) = B as well as A. A와 B의 순서가 바뀐다.",
  n=["B as well as A가 not only A but also B와 같은 뜻이므로", "either ~ or는 ‘둘 중 하나’이고 빈칸에 붙여 쓸 수도 없으므로", "neither ~ nor는 ‘둘 다 아닌’이라 뜻이 반대이므로", "not A but B는 ‘A가 아니라 B’라 뜻이 다르므로", "both와 and는 both A and B로 떼어 쓰므로"],
  st="① 첫 문장의 표현을 확인한다: {0}. → ② 둘째 문장의 틀에 맞는 같은 뜻의 표현을 찾는다: {1}. → ③ 정답은 {a}.",
  R=("not only A but also B(A뿐 아니라 B도)", "B(her sister)가 앞에 나와 있으므로 B as well as A"), B=("not only A but also B", "B(helpful)가 앞에 나와 있으므로 B as well as A"), C=("both A and B(A와 B 둘 다)", "both를 빼면 A and B"),
  D=("neither A nor B(A도 B도 아닌)", "동사를 부정(doesn't like)했으므로 A or B"), E=("B as well as A", "not only A 뒤이므로 but also B"), F=("both A and B(A와 B 둘 다)", "both를 빼면 A and B"))
RV(3, 125, "D", v="수정(내용)", why="정답(or) 확인. 다만 오답 unless·because·although는 두 명사 사이에 올 수 없어 형태만으로 지워진다. 원문항의 오답은 모두 상관접속사의 짝이었다. 빈칸 밑줄이 괄호로 바뀐 점도 원문항과 다르다.", fix="오답을 상관접속사에 쓰이는 말로, 밑줄 빈칸으로")

X(3, 126, r="and는 나란히 이어짐, but은 대조, or는 선택, because는 이유, so는 결과를 나타낸다.",
  n=["but은 대조라 ‘치고 … 부른다’와 맞지 않으므로", "and는 두 사실을 나란히 이으므로", "because는 이유라 뜻이 맞지 않으므로", "so는 결과라 뜻이 맞지 않으므로", "or는 선택이라 뜻이 맞지 않으므로"],
  st="① {2}에서 두 절의 관계를 읽는다: {0}. → ② {1} → ③ 정답은 {a}.",
  R=("‘치고 … 부른다’(나란히 이어짐)", "두 사실을 나란히 잇는 접속사는 and다.", "괄호 속 우리말"), B=("‘치고 … 부른다’(첨가)", "두 사실을 나란히 잇는 접속사는 and다.", "발문의 우리말"), C=("‘피곤하지만’(대조)", "앞뒤가 반대되는 내용을 잇는 접속사는 but이다.", "발문의 우리말"),
  D=("‘차와 커피 중 어느 것’(선택)", "둘 가운데 하나를 고를 때는 or다.", "발문의 우리말"), E=("‘아팠기 때문에’(이유)", "뒤에 이유를 이끄는 접속사는 because다.", "발문의 우리말"), F=("‘비가 와서 … 취소했다’(결과)", "뒤에 결과를 이끄는 접속사는 so다.", "발문의 우리말"))
RV(3, 126, "B", fx=True, why="수정 예시의 정답(and)과 위치(②)가 원문항과 같아, 보기 순서를 바꿔 정답 위치를 ④로 옮겼다.")

X(3, 127, r="neither A nor B는 ‘A도 B도 아닌’이다. neither는 nor와, either는 or와 짝을 이룬다. 조동사 뒤의 A, B는 동사원형이다.",
  n=["neither는 and와 짝을 이루지 않고 can 뒤에 reads, writes를 쓸 수 없으므로", "either A or B는 ‘읽거나 쓸 수 있다’는 뜻이므로", "neither는 so와 짝을 이루지 않으므로", "either는 nor와 짝을 이루지 않으므로", "neither A nor B + 동사원형으로 바르게 옮겼으므로"],
  st="① 우리말이 둘 다 부정임을 확인한다: {0}. neither A nor B를 쓴다. → ② 짝을 확인한다: neither는 nor와, either는 or와 짝을 이룬다. can 뒤의 동사는 원형이다. → ③ 정답은 {n}.",
  R="‘읽을 수도 쓸 수도 없다’", B="‘읽을 수도 쓸 수도 없다’", C="‘노래도 못 부르고 춤도 못 춘다’", D="‘수영도 달리기도 못한다’", E="‘버스도 기차도 탈 수 없다’", F="‘영어도 프랑스어도 못한다’")
RV(3, 127, "C", v="수정(내용)", why="정답 확인. 다만 우리말과 정답 문장(She can neither sing nor dance.)이 같은 단원 3-123의 C와 똑같다. 같은 유형끼리 묶어 쓰면 같은 문항이 두 번 나온다.", fix="우리말과 문장을 새로")

X(3, 128, r="not only A but also B는 ‘A뿐만 아니라 B도’이다. not only와 but also를 떼거나 순서를 바꾸지 않고 A, B 바로 앞에 둔다.",
  n=["not only A but also B 어순으로 바르게 배열했으므로", "not이 be동사 앞에 와서 어순이 틀렸으므로", "only not이 아니라 not only로 써야 하므로", "not과 only를 떼어 쓸 수 없으므로", "also but이 아니라 but also로 써야 하므로"],
  st="① ‘A뿐만 아니라 B도’는 not only A but also B다. A와 B를 정한다: {0}. → ② {1} 뒤에 not only A but also B를 통째로 놓는다. not only와 but also는 떼거나 순서를 바꾸지 않는다. → ③ 정답은 {n}.",
  R=("A는 beautiful, B는 smart", "She is"), B=("A는 beautiful, B는 smart", "She is"), C=("A는 kind, B는 funny", "Tom is"), D=("A는 English, B는 French", "Jane speaks"), E=("A는 Busan, B는 Seoul", "We visited"), F=("A는 swimming, B는 running", "He is good at"))

X(3, 129, r="Unless = If ~ not. If를 Unless로 바꾸면 if절의 not을 지우고, 주절은 그대로 둔다.",
  n=["unless에 not의 뜻이 있어 don't를 또 쓰면 안 되므로", "If ~ not을 Unless로 바꾸고 주절은 그대로 두었으므로", "not을 남겼고 주절도 won't로 뒤집었으므로", "주절을 won't로 뒤집어 뜻이 달라졌으므로", "unless절에 동사 없이 leaving만 썼으므로"],
  st="① Unless = If ~ not이다. if절의 부정({0})을 지우고 If를 Unless로 바꾼다. → ② {1} → ③ 주절({2})은 그대로 둔다. 정답은 {n}.",
  R=("don't", "unless절은 Unless we leave now가 된다.", "we'll miss the bus"), B=("don't", "unless절은 Unless we leave now가 된다.", "we'll miss the bus"), C=("don't", "unless절은 Unless you hurry가 된다.", "you'll be late"),
  D=("doesn't", "unless절은 Unless Tom calls가 된다. doesn't가 빠지면서 동사에 -s가 붙는다.", "I won't know"), E=("doesn't", "unless절은 Unless it stops raining이 된다. doesn't가 빠지면서 동사에 -s가 붙는다.", "we can't go"),
  F=("doesn't", "unless절은 Unless Jane studies가 된다. doesn't가 빠지면서 동사에 -s가 붙는다.", "she won't pass"))
RV(3, 129, "B", fx=True, why="수정 예시의 오답 둘이 If·When으로 시작해 발문(‘Unless를 사용하여’)만 보고 지워졌다. 원문항처럼 다섯 보기를 모두 Unless로 시작하게 고쳤다.")
RV(3, 129, "CDEF", v="수정(내용)", why="정답 확인. 다만 발문이 ‘Unless를 사용하여’ 고치라고 했는데 오답 셋이 When·If·Because로 시작해 발문만 보고 지워진다. 원문항은 다섯 보기가 모두 Unless로 시작하고, not을 겹쳐 쓴 문장과 주절의 뜻을 뒤집은 문장이 오답이다.", fix="다섯 보기를 모두 Unless로 시작하게")

X(3, 130, r="that절이 주어이면 단수 동사를 쓴다. that절 안은 ‘주어 + 동사’ 어순이다. 가주어 It을 쓰고 that절을 뒤로 보낼 수 있다.",
  pre=["문장별 판정: ㉠ X. that절 주어는 단수 취급하므로 is. ㉡ O. 가주어 It + 진주어 that절. ㉢ O. that절 주어 + 단수 동사 is. ㉣ X. that절 안은 주어 + 동사 어순(that he is a good boy)."],
  n=["㉠이 틀렸으므로", "㉠이 틀렸으므로", "㉡과 ㉢이 모두 옳으므로", "㉣이 틀렸으므로", "㉣이 틀렸으므로"],
  st="① that절이 주어인 문장은 문장의 동사가 단수인지 본다. → ② that절 안이 ‘주어 + 동사’ 어순인지, 그 안의 동사가 주어와 맞는지 본다. → ③ {0} 옳은 문장만 고른 {a}가 정답이다.",
  R="㉠은 are(is), ㉣은 that is he(that he is)가 틀렸다.", B="ㄱ은 are(is), ㄹ은 he are(he is)가 틀렸다.", C="ㄴ은 are(is), ㄹ은 they was(they were)가 틀렸다.", D="ㄹ은 We knows(We know)가 틀렸다.", E="ㄷ은 he were(he was), ㅁ은 are(is)가 틀렸다.",
  F="ㄷ은 are(is)가 틀렸다.")
RV(3, 130, "D", fx=True, why="수정 예시의 정답 조합과 위치(㉡, ㉢ ③)가 원문항과 같아, 문장 순서를 바꿔 정답을 ㉡, ㉣(④)로 했다.")
